#include <iostream>
#include <cmath>
#include <algorithm>
using namespace std;

int n, m, k, a, b;

int main() {
    cin >> n >> m >> k >> a >> b;

    int x = a / (m * k) + 1;
    if (a == (x - 1) * m * k)
        x--;

    int y = b / (m * k) + 1;
    if (b == (y - 1) * m * k)
        y--;

    int d = min(abs(x - y), n - abs(x - y));
    int cek = d * 15;

    int q1 = a - (x - 1) * m * k;
    int f1 = (q1 / k) + 1;
    if (q1 % k == 0)
        f1--;

    int q2 = b - (y - 1) * m * k;
    int f2 = (q2 / k) + 1;
    if (q2 % k == 0)
        f2--;

    if (d == 0) {
        cek += min(5 * abs(f2 - f1), 10 + abs(f2 - f1));
    } else {
        cek += min(5 * (f2 - 1), 9 + f2);
        cek += min(5 * (f1 - 1), 9 + f1);
    }

    cout << cek;
    return 0;
}

